/// Resolve a glyph key through the active set.
pub fn glyph(key: &str, set: Set) -> &'static str {
    let (n, u, a) = match glyphs().get(key) {
        Some(v) => *v,
        None => return "?",
    };
    match set {
        Set::Nerd => n,
        Set::Unicode => u,
        Set::Ascii => a,
    }
}
